"use client";

import { useState } from "react";
import { ChevronDown, ChevronUp, Thermometer, Droplets, Wind, Weight } from "lucide-react";

const SENSORS = [
  {
    icon: Thermometer,
    name: "Temperature Sensor",
    purpose: "Measures compost temperature.",
    detail:
      "Temperature provides an indirect indication of microbial activity. During active composting, heat is generated by microbial metabolism. However, temperature alone does not directly measure microbial populations or species diversity.",
    color: "text-red-400",
    bg: "bg-red-900/20 border-red-700/20",
  },
  {
    icon: Droplets,
    name: "Moisture Sensor",
    purpose: "Measures moisture level in the compost.",
    detail:
      "Optimal moisture (50–70%) supports microbial activity and decomposition. Too dry (<40%) inhibits microbial growth; too wet (>80%) can restrict oxygen and promote anaerobic conditions.",
    color: "text-sky-400",
    bg: "bg-sky-900/20 border-sky-700/20",
  },
  {
    icon: Wind,
    name: "Gas Sensors (CO₂, CH₄, NH₃, H₂S)",
    purpose: "Monitor gases associated with composting and decomposition.",
    detail:
      "CO₂ indicates microbial respiration. CH₄ and H₂S may indicate anaerobic conditions (insufficient oxygen). NH₃ may indicate nitrogen-rich material decomposition or C/N ratio imbalance. Readings are monitoring indicators and should be interpreted in context.",
    color: "text-violet-400",
    bg: "bg-violet-900/20 border-violet-700/20",
  },
  {
    icon: Weight,
    name: "Load Cell (Weight Sensor)",
    purpose: "Measures the mass of the compost bin contents.",
    detail:
      "Weight reduction over time indicates material loss through decomposition (CO₂ and water vapour release). It is a useful progress indicator but does NOT alone confirm that the compost is mature or pathogen-free.",
    color: "text-lime-400",
    bg: "bg-lime-900/20 border-lime-700/20",
  },
] as const;

export default function SensorInfo() {
  const [open, setOpen] = useState(false);

  return (
    <div className="rounded-2xl bg-[#0d1f0d]/80 border border-green-800/30 shadow-xl shadow-black/20 overflow-hidden">
      <button
        id="sensor-info-toggle"
        onClick={() => setOpen((p) => !p)}
        className="w-full flex items-center justify-between p-5 hover:bg-white/[0.02] transition-colors"
      >
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 rounded-xl bg-green-900/40 border border-green-700/30 flex items-center justify-center">
            <Wind className="w-4 h-4 text-green-400" />
          </div>
          <div className="text-left">
            <h2 className="text-sm font-bold text-slate-100">About the Sensors</h2>
            <p className="text-[11px] text-slate-500">
              Technical overview of monitored parameters
            </p>
          </div>
        </div>
        {open ? (
          <ChevronUp className="w-4 h-4 text-slate-400" />
        ) : (
          <ChevronDown className="w-4 h-4 text-slate-400" />
        )}
      </button>

      {open && (
        <div className="px-5 pb-5 grid grid-cols-1 md:grid-cols-2 gap-4 border-t border-white/5 pt-4 fade-in">
          {SENSORS.map((sensor) => (
            <div
              key={sensor.name}
              className={`rounded-xl border p-4 ${sensor.bg}`}
            >
              <div className="flex items-center gap-2 mb-2">
                <sensor.icon className={`w-4.5 h-4.5 ${sensor.color}`} size={18} />
                <h3 className={`text-[13px] font-bold ${sensor.color}`}>{sensor.name}</h3>
              </div>
              <p className="text-[12px] text-slate-300 font-medium mb-2">{sensor.purpose}</p>
              <p className="text-[11px] text-slate-500 leading-relaxed">{sensor.detail}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
